from pathlib import Path
import json
r=Path('/workspace/.ashveil-planned/v378-culler-facing-parts')
roles=['chassis','driveUpper','driveLower','foot','scytheUpper','scytheBlade']
rects={'LEFT':[[113,139,489,345],[716,175,252,322],[1146,91,251,424],[157,714,345,219],[681,555,271,395],[1176,555,271,421]],'RIGHT':[[84,109,495,390],[731,155,265,348],[1179,107,283,413],[146,702,359,244],[685,569,266,383],[1195,570,281,407]],'BACK':[[107,77,391,395],[701,148,231,321],[1212,88,234,402],[139,698,329,221],[721,571,231,362],[1194,539,260,427]]}
pins={'LEFT':{'chassis':{'opticsGraphicCenter':[200,377],'tankGraphicCenter':[466,272],'nearFrontBoss':[265,445],'rearGraphicBoss':[578,264]},'driveUpper':{'proximalGraphicCap':[931,244],'distalGraphicCap':[809,447]},'driveLower':{'proximalGraphicCap':[1360,156],'distalGraphicCap':[1231,463]},'foot':{'ankleGraphicCap':[325,794],'soleChordA':[244,908],'soleChordB':[376,923]},'scytheUpper':{'proximalGraphicCap':[913,633],'distalGraphicCap':[783,899]},'scytheBlade':{'proximalGraphicCap':[1273,622],'bladeTip':[1295,966]}},'RIGHT':{'chassis':{'opticsGraphicCenter':[512,407],'tankGraphicCenter':[207,308],'nearFrontBoss':[409,454],'rearGraphicBoss':[145,242]},'driveUpper':{'proximalGraphicCap':[769,239],'distalGraphicCap':[911,456]},'driveLower':{'proximalGraphicCap':[1219,186],'distalGraphicCap':[1380,477]},'foot':{'ankleGraphicCap':[296,784],'soleChordA':[242,926],'soleChordB':[384,932]},'scytheUpper':{'proximalGraphicCap':[842,647],'distalGraphicCap':[783,901]},'scytheBlade':{'proximalGraphicCap':[1255,638],'bladeTip':[1346,963]}},'BACK':{'chassis':{'rearVentGraphicCenter':[320,389],'tankGraphicCenter':[191,287],'nearLeftHollowSocket':[224,444],'nearRightHollowSocket':[407,441]},'driveUpper':{'proximalGraphicCap':[738,218],'distalGraphicCap':[842,421]},'driveLower':{'proximalGraphicCap':[1255,161],'distalGraphicCap':[1358,447]},'foot':{'ankleGraphicCap':[304,787],'soleChordA':[231,902],'soleChordB':[376,901]},'scytheUpper':{'proximalGraphicCap':[757,649],'distalGraphicCap':[842,881]},'scytheBlade':{'proximalGraphicCap':[1231,613],'bladeTip':[1318,959]}}}
rows={d:[{'part':p,'crop':rects[d][i],'graphicPoints':pins[d][p]}for i,p in enumerate(roles)]for d in rects}
(r/'records/manual-graphic-points.json').write_text(json.dumps(rows,indent=2)+'\n')
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><title>v378 directional part source review</title><style>*{box-sizing:border-box}body{margin:0;color:#ddd3c0;background:#14191e;font:16px sans-serif}h1,h2,p{margin:10px 16px}.references{display:flex;gap:20px;padding:10px}.grid{display:grid;grid-template-columns:repeat(3,500px);gap:10px;padding:10px}.card{border:1px solid #776d58;padding:8px;background:#293137}.card h3{margin:5px}svg{display:block;image-rendering:pixelated}svg text{fill:#ffdb68;stroke:#111;stroke-width:2px;paint-order:stroke;font:12px monospace}.plate{background:#101619}.light .plate{background:#ddd}.checker{background:conic-gradient(#87939b 25%,#414d54 0 50%,#87939b 0 75%,#414d54 0);background-size:16px 16px}.caption{font:13px monospace;color:#c1b6a1}</style><h1>v378 LEFT / RIGHT / BACK · source-only six parts</h1><p>Unchanged PNG bytes; crop/markers only. No rig, no animation frames, no rear-face/3D/inner-edge approval.</p>'''
refs=json.loads((r/'records/references.json').read_text())
def svg(source,rect,id,width,height,points=None,plate='plate'):
 x,y,w,h=rect;marks=''
 for name,(px,py) in (points or {}).items():marks+=f'<circle cx="{px}" cy="{py}" r="5" fill="none" stroke="#fcbd5f" stroke-width="1"/><path d="M{px-8} {py}h16M{px} {py-8}v16" stroke="#ed7295" stroke-width=".8"/><text x="{px+8}" y="{py-8}">{name}:{px},{py}</text>'
 return f'<svg class="{plate}" width="{width}" height="{height}" viewBox="{x} {y} {w} {h}"><defs><clipPath id="clip-{id}"><rect x="{x}" y="{y}" width="{w}" height="{h}"/></clipPath></defs><g clip-path="url(#clip-{id})"><image href="/{source}" width="{1254 if source=="canon.png" else 1536}" height="{1254 if source=="canon.png" else 1024}"/>{marks}</g></svg>'
for d,parts in rows.items():
 html+=f'<section id="{d.lower()}"><h2>{d} canonical + generated6 source regions</h2><div class="references"><div>canonical {d}{svg("canon.png",refs["canonicalFirstPoseRegions"][d],d+"canon",350,260)}</div><div>FRONT material identity only{svg("front.png",[155,76,361,382],d+"front",260,260)}</div><div>generated direction chassis{svg(d.lower()+".png",parts[0]["crop"],d+"bodyref",480,260)}</div></div><div class="grid">'
 for i,p in enumerate(parts):html+=f'<div class="card"><h3>{d} {i+1} {p["part"]}</h3>{svg(d.lower()+".png",p["crop"],d+p["part"],480,310,p["graphicPoints"])}<p class="caption">source rect {p["crop"]}</p></div>'
 html+='</div></section>'
html+='</html>'; (r/'review.html').write_text(html)
